fn gcd_calc(m: u32, n: u32) -> u32 {
    // Inputs are both > 0, enforce via debug assert for robustness
    debug_assert!(m > 0 && n > 0, "Inputs must be strictly positive");

    let mut a = m;
    let mut b = n;

    // Use subtraction-based Euclid algorithm
    while a != b {
        if a > b {
            a = a - b; // a - b is strictly positive because a > b
        } else {
            b = b - a; // b - a is strictly positive because b > a
        }
    }

    // At loop end, a == b == gcd(m, n)
    a
}